--
-- Table structure for table `invoice`
--

DROP TABLE IF EXISTS `invoice`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `invoice` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `create_time` datetime(6) NOT NULL,
  `update_time` datetime(6) NOT NULL,
  `date` date NOT NULL,
  `invoice_number` varchar(20) NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `contract_id` bigint NOT NULL,
  `customer_id` bigint NOT NULL,
  `invoice_man_id` bigint NOT NULL,
  `is_delete` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `cono_invoice_contract_id_37b0ca15_fk_contract_id` (`contract_id`),
  KEY `cono_invoice_customer_id_33f8ffca_fk_customer_id` (`customer_id`),
  KEY `cono_invoice_invoice_man_id_da713f92_fk_user_id` (`invoice_man_id`),
