  `update_time` datetime(6) NOT NULL,
  `quantity` int NOT NULL,
  `unit` int NOT NULL,
  `configuration` longtext NOT NULL,
  `effective_date` date NOT NULL,
  `delivery_date` date NOT NULL,
  `contract_id` bigint NOT NULL,
  `product_id` bigint NOT NULL,
  `productcategory_id` bigint NOT NULL,
  `production_man_id` bigint NOT NULL,
  `completed` tinyint(1) NOT NULL,
  `contract_reserve` varchar(20) DEFAULT NULL,
  `completed_status` int NOT NULL,
  `is_delete` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `cono_productionplan_contract_id_9fd66b37_fk_cono_contract_id` (`contract_id`),
  KEY `cono_productionplan_product_id_b7b1fe6a_fk_cono_product_id` (`product_id`),
