  KEY `cono_productionplan_production_man_id_87c08f0f_fk_cono_user_id` (`production_man_id`),
  CONSTRAINT `cono_productionplan_contract_id_9fd66b37_fk_cono_contract_id` FOREIGN KEY (`contract_id`) REFERENCES `contract` (`id`),
  CONSTRAINT `cono_productionplan_product_id_b7b1fe6a_fk_cono_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`),
  CONSTRAINT `cono_productionplan_productcategory_id_6cbb62fc_fk_cono_prod` FOREIGN KEY (`productcategory_id`) REFERENCES `productcategory` (`id`),
  CONSTRAINT `cono_productionplan_production_man_id_87c08f0f_fk_cono_user_id` FOREIGN KEY (`production_man_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=439 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
