  `max_in_temp` varchar(20) NOT NULL,
  `max_pressure` varchar(20) NOT NULL,
  `min_flow` varchar(20) NOT NULL,
  `min_pressure` varchar(20) NOT NULL,
  `product_id` bigint NOT NULL,
  `is_delete` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `productlabel_product_id_0097e982_fk_product_id` (`product_id`),
  CONSTRAINT `productlabel_product_id_0097e982_fk_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`)
